#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
using pii = pair<int, int>;

template<typename T, typename U> inline T min_assign(T& a, const U& b) { return (b < a) ? (a = b, a) : a; }
template<typename T, typename U> inline T max_assign(T& a, const U& b) { return (a < b) ? (a = b, a) : a; }

#define loop(i, a, b) for (int i = (a), _e = (b); i < _e; ++i)
#define rep(i, n) loop(i, 0, n)

const int MAX_N = 205;
const int MAX_M = MAX_N * MAX_N;
#define prev some

int readInt() { int x; cin >> x; return x; }

int prev_edge[MAX_M], visited_node[MAX_N], head_node[MAX_N], edge_src[MAX_M], edge_cap[MAX_M], edge_dst[MAX_M], edge_cnt = 0;
int grid_in[MAX_N][MAX_N], grid_out[MAX_N][MAX_N], red_flag[MAX_N][MAX_N], block_flag[MAX_N][MAX_N];
int dist_table[MAX_N][MAX_N], temp_var, dist_red[MAX_N], visited_bfs[MAX_N];
pii queue_bfs[MAX_N];
const int dX[4] = {0, -1, 0, 1};
const int dY[4] = {1, 0, -1, 0};

void add_edge(int u, int v, int uv_cap, int vu_cap) {
	edge_src[edge_cnt] = u; edge_dst[edge_cnt] = v; edge_cap[edge_cnt] = uv_cap; prev_edge[edge_cnt] = head_node[u]; head_node[u] = edge_cnt++;
	edge_src[edge_cnt] = v; edge_dst[edge_cnt] = u; edge_cap[edge_cnt] = vu_cap; prev_edge[edge_cnt] = head_node[v]; head_node[v] = edge_cnt++;
}

int dfs_flow(int v, int t, int f = 2000000000) {
	if (v == t) return f;
	if (visited_node[v]++) return 0;
	for (int e = head_node[v]; ~e; e = prev_edge[e]) if (edge_cap[e]) {
		int u = edge_dst[e];
		int flow = dfs_flow(u, t, min(f, edge_cap[e]));
		if (flow) { edge_cap[e] -= flow; edge_cap[e ^ 1] += flow; return flow; }
	}
	return 0;
}

int compute_flow(int s, int t) {
	int total = 0;
	for (;;) {
		memset(visited_node, 0, sizeof visited_node);
		int delta = dfs_flow(s, t);
		total += delta;
		if (!delta) break;
	}
	return total;
}

int main() {
	ios::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);
	int n = readInt(), dt = readInt();
	memset(head_node, -1, sizeof head_node);
	memset(dist_table, 63, sizeof dist_table);
	rep(i, MAX_N) dist_table[i][i] = 0;
	rep(x, n) rep(y, n) {
		char c; cin >> c;
		if (c == 'Y') block_flag[x][y] = 1;
		else if (c == 'Z') red_flag[x][y] = 1;
		else grid_in[x][y] = c - '0';
	}
	rep(x, n) rep(y, n) {
		char c; cin >> c;
		if (c != 'Y' && c != 'Z') {
			grid_out[x][y] = c - '0';
			rep(d, 4) {
				int nx = x + dX[d], ny = y + dY[d];
				if (nx >= 0 && ny >= 0 && nx < n && ny < n && !block_flag[nx][ny] && !red_flag[nx][ny])
					dist_table[x * n + y][nx * n + ny] = 1;
			}
		}
	}
	int total_nodes = n * n;
	rep(k, total_nodes) rep(i, total_nodes) rep(j, total_nodes)
		if (dist_table[i][k] + dist_table[k][j] < dist_table[i][j])
			dist_table[i][j] = dist_table[i][k] + dist_table[k][j];
	int qh = 0, qt = 0;
	memset(dist_red, 63, sizeof dist_red);
	rep(i, n) rep(j, n)
		if (red_flag[i][j]) {
			queue_bfs[qt++] = {i, j};
			dist_red[i * n + j] = 0;
		}
	while (qh != qt) {
		auto cur = queue_bfs[qh++];
		int x = cur.first, y = cur.second;
		rep(d, 4) {
			int nx = x + dX[d], ny = y + dY[d];
			if (nx >= 0 && ny >= 0 && nx < n && ny < n && !block_flag[nx][ny] && !red_flag[nx][ny] && dist_red[nx * n + ny] > 1e9) {
				dist_red[nx * n + ny] = dist_red[x * n + y] + 1;
				queue_bfs[qt++] = {nx, ny};
			}
		}
	}
	int sink_node = MAX_N - 1, source_node = MAX_N - 2;
	rep(start_node, total_nodes) {
		memset(visited_bfs, 0, sizeof visited_bfs);
		qh = 0; qt = 0;
		int sx = start_node / n, sy = start_node % n;
		if (block_flag[sx][sy] || red_flag[sx][sy]) continue;
		queue_bfs[qt++] = {sx, sy};
		visited_bfs[start_node] = 1;
		while (qh != qt) {
			int x = queue_bfs[qh].first, y = queue_bfs[qh++].second;
			if (dist_table[start_node][x * n + y] <= dt)
				add_edge(start_node << 1, (x * n + y) << 1 | 1, 1000, 0);
			if (dist_table[start_node][x * n + y] == dist_red[x * n + y]) continue;
			rep(d, 4) {
				int nx = x + dX[d], ny = y + dY[d], nid = nx * n + ny;
				if (nx >= 0 && ny >= 0 && nx < n && ny < n && !block_flag[nx][ny] && !red_flag[nx][ny] && dist_table[start_node][nid] <= dist_red[nid] && dist_table[start_node][nid] <= dt && dist_table[start_node][nid] > dist_table[start_node][x * n + y] && !visited_bfs[nid]) {
					queue_bfs[qt++] = {nx, ny};
					visited_bfs[nid] = 1;
				}
			}
		}
	}
	rep(i, total_nodes) add_edge(source_node, i << 1, grid_in[i / n][i % n], 0);
	rep(i, total_nodes) add_edge((i << 1) | 1, sink_node, grid_out[i / n][i % n], 0);
	cout << compute_flow(source_node, sink_node);
}
